CREATE TABLE agents      (tenant_id text NOT NULL, id text NOT NULL, version int NOT NULL DEFAULT 1, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, id));
CREATE TABLE connections (tenant_id text NOT NULL, id text NOT NULL, kind text NOT NULL CHECK (kind = 'mcp'), url text NOT NULL, tools jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, id));
CREATE TABLE runs        (tenant_id text NOT NULL, id text PRIMARY KEY, agent_id text NOT NULL, agent_version int NOT NULL, status text NOT NULL, waiting_reason text, idempotency_key text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key));
CREATE TABLE events      (tenant_id text NOT NULL, run_id text NOT NULL REFERENCES runs(id), seq int NOT NULL, type text NOT NULL, payload jsonb NOT NULL, labels text[] NOT NULL, agent_version int NOT NULL, created_at timestamptz NOT NULL, prev_hash char(64) NOT NULL, hash char(64) NOT NULL, subject_key_id text, payload_enc bytea, PRIMARY KEY (run_id, seq));
CREATE TABLE queue       (run_id text PRIMARY KEY, tenant_id text NOT NULL, priority int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_by text, locked_at timestamptz);
CREATE TABLE webhooks    (tenant_id text NOT NULL, id text PRIMARY KEY, url text NOT NULL, secret text NOT NULL, events text[] NOT NULL);
CREATE TABLE webhook_deliveries (id text PRIMARY KEY, tenant_id text NOT NULL, webhook_id text NOT NULL REFERENCES webhooks(id), event_id text NOT NULL, type text NOT NULL, body text NOT NULL, attempts int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text);
REVOKE UPDATE, DELETE ON events FROM PUBLIC;
